def basic_calculator(s):
    total = number = 0
    sign = 1
    stack = []
    for char in s:
        if char.isdigit():
            number = number * 10 + int(char)
        elif char in "+-":
            total += sign * number
            number = 0
            sign = 1 if char == "+" else -1
        elif char == "(":
            stack.extend((total, sign))
            total, sign = 0, 1
        elif char == ")":
            total += sign * number
            number = 0
            total = stack.pop() * total + stack.pop()
    return total + sign * number

